{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver swims through a shattered mirror into the ruined city.",
      "visual_description": "A jagged mirror frame stands in a cobblestone square; the glass diver emerges, helmet gleaming, coat reflecting broken city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the Cartographer unfurls a map in a collapsed hall.",
      "visual_description": "Mara stands under a crumbling arch, ink-stained coat catching dust motes, brass compass in hand, studying a parchment map.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers to life on a stone pillar.",
      "visual_description": "An oil lamp with a single glowing eye in the flame sits atop a mossy pillar, casting eerie shadows on ruined walls.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The sleeping tax collector snores behind a stack of ledgers.",
      "visual_description": "A drowsy figure slumped over a ledger book pillow, stamped papers stuck to sleeves, in a roofless chamber of the old treasury.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "The tin fox scampers ahead through a broken gate.",
      "visual_description": "A small metal fox with key-wind tail and blue glass eyes leaps over rubble under the rusted portcullis of a castle gate.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara and the glass diver meet at the fountain plaza.",
      "visual_description": "A dried fountain surrounded by fallen banners; the glass diver and Mara exchange nods as the oracle lamp hovers nearby.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "The lamp's eye narrows, flame casting red light on a twisted spire that looms through mist.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The group approaches the cursed tower's base.",
      "visual_description": "Cracked steps lead to an iron-bound door; ancient symbols glow faintly on the stone; the tin fox sniffs the threshold.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Inside, the sleeping tax collector has wandered in and dozes on a pile of old tax rolls.",
      "visual_description": "A circular room with crumbling shelves; the tax collector sleeps atop a heap of dusty papers, stamped forms stuck to his sleeves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "The glass diver peers through a window into a locked chamber.",
      "visual_description": "The diver presses a gloved hand to a frosted window, seeing a shadowy room beyond; his helmet fogs slightly.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Mara finds a secret passage marked on her map.",
      "visual_description": "She traces a line on the parchment, then pushes a loose stone; a hidden doorway grinds open, revealing a dark corridor.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "The tin fox triggers a trap but escapes unscathed.",
      "visual_description": "A pressure plate clicks; a net of chains drops from the ceiling, but the tiny fox darts aside, key-wind tail spinning.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The oracle lamp reveals a magic door that only opens at dusk.",
      "visual_description": "The lamp's flame casts a beam on a door inscribed with sun and moon phases; the eye watches the shadows lengthen.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The group waits for sunset, the glass diver calming the frightened townspeople.",
      "visual_description": "A few huddled figures in torn cloaks gather near the door; the glass diver speaks softly, his helmet reflecting their worried faces.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The magic door swings open as the last light fades.",
      "visual_description": "Golden light spills from the doorway as the sun sets; Mara gestures, tin fox dashes through, oracle lamp bobs after.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols march down the main avenue.",
      "visual_description": "Silhouettes of marching figures in plate armor, torches held high, pass under tattered royal banners as the group hides in a niche.",
      "characters": ["glass_diver", "mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The sleeping tax collector wakes and stumbles onto the escape bridge.",
      "visual_description": "He blinks, ledger still in hand, as he steps onto a stone bridge arching over a dry moat; the group follows cautiously.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The glass diver dives through a mirror on the far side to seal the escape.",
      "visual_description": "At the bridge's end, a standing mirror reflects the ruined city; the glass diver leaps through, the surface ripples, then solidifies, leaving only the group on the safe side.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

